contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am, uint _w) public payable {
        require(address(this).balance >= _am, "need funds");
        // fund the test contract so it can call Collect with value
        require(_am > 0, "amount must be positive");

        // set up: make a Put so msg.sender (this test contract) has a Holder entry
        c.Put{value: _w}(0);

        uint beforeBalance = address(this).balance;
        uint beforeC = address(c).balance;

        // deciding call: Collect is payable and should not revert for any inputs
        bool reverted;
        try c.Collect{value: _am}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // general rule: Collect never reverts regardless of _am/_w combination
        assert(!reverted);
    }

    receive() external payable {}
}

