contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _unlockTime, uint _deposit, uint _am) public payable {
        require(address(this).balance >= _deposit);

        uint cBalanceBefore = address(c).balance;

        c.Put{value: _deposit}(_unlockTime);

        (uint unlockTime, uint balance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        uint cBalanceMid = address(c).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        bool collectible = (balance >= minSum)
            && (balance >= _am)
            && (block.timestamp > unlockTime)
            && (cBalanceMid >= _am);

        assert(
            (collectible && !reverted
                && balanceAfter == balance - _am
                && cBalanceAfter == cBalanceMid - _am
                && unlockTimeAfter == unlockTime)
            || (!collectible && !reverted
                && balanceAfter == balance
                && cBalanceAfter == cBalanceMid
                && unlockTimeAfter == unlockTime
                && reverted == false)
        );
    }

    receive() external payable {}
}

