contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 unlockTime, uint256 collectAmount) public payable {
        require(address(this).balance >= amount);

        c.Put{value: amount}(unlockTime);

        (uint256 beforeUnlock, uint256 beforeBal) = c.Acc(msg.sender);

        (bool collectOk, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        (uint256 afterUnlock, uint256 afterBal) = c.Acc(msg.sender);
        uint256 minSum = c.MinSum();
        uint256 t = block.timestamp;
        bool shouldCollect = beforeBal >= minSum && beforeBal >= collectAmount && t > beforeUnlock;

        assert(collectOk == shouldCollect);
        assert(shouldCollect ? (afterUnlock == beforeUnlock && afterBal <= beforeBal) : (afterUnlock == beforeUnlock && afterBal == beforeBal));
    }

    receive() external payable {}
}

