contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.Put{value: depositAmount}(unlockTime);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc( address(this) );

        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

        (uint afterUnlockTime, uint afterBalance) = c.Acc( address(this) );

        bool eligible = (beforeBalance >= c.MinSum() && beforeBalance >= collectAmount && block.timestamp > beforeUnlockTime);

        // General rule: Collect must not revert, and it performs exactly the eligible transfer. If the
        // record is eligible, balance decreases by collectAmount and the contract loses that much Ether;
        // otherwise nothing changes, and unlockTime is untouched either way.
        assert(
            !reverted &&
            afterUnlockTime == beforeUnlockTime &&
            (
                eligible
                    ? (afterBalance == beforeBalance - collectAmount &&
                       address(c).balance == beforeContractBalance - collectAmount)
                    : (afterBalance == beforeBalance && address(c).balance == beforeContractBalance)
            )
        );
    }
}

