contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint deposit, uint unlockTime, uint amount) public payable {
        require(address(this).balance >= deposit);
        require(deposit >= 0 && amount >= 0);

        c.Put{value: deposit}(unlockTime);

        uint beforeBalance = c.Acc(address(this)).balance;
        uint beforeUnlock = c.Acc(address(this)).unlockTime;
        uint minSum = c.MinSum();
        uint cBefore = address(c).balance;

        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = c.Acc(address(this)).balance;
        uint cAfter = address(c).balance;

        bool shouldSucceed = beforeBalance >= minSum && beforeBalance >= amount && block.timestamp > beforeUnlock;
        if (!shouldSucceed) {
            assert(reverted && afterBalance == beforeBalance && cAfter == cBefore);
        } else {
            assert(!reverted && afterBalance == beforeBalance - amount && cAfter == cBefore - amount);
        }
    }

    receive() external payable {}
}
